-- Restores the sequence-backed DEFAULT that add_salon_public_id (20260814190000) set on
-- salons.publicId. It was silently dropped by the very next migration
-- (20260814185740_add_booking_selected_style_name / "ALTER TABLE salons ALTER COLUMN publicId
-- DROP DEFAULT") because that migration was generated by `prisma migrate dev`, whose diff engine
-- only trusts schema.prisma as the source of truth — the earlier hand-written raw-SQL DEFAULT was
-- invisible to it (schema.prisma had no `@default(...)` annotation on the field at the time), so
-- it "reconciled" the DB by removing a default schema.prisma didn't know about.
--
-- Fix going forward: schema.prisma's Salon.publicId now carries
-- `@default(dbgenerated("..."))`, which tells Prisma's migrate diff engine this column's default
-- is externally managed and must never be touched by a generated migration.
ALTER TABLE "salons" ALTER COLUMN "publicId" SET DEFAULT 'BC-SHOP-' || LPAD(nextval('salon_public_id_seq')::text, 6, '0');
